CREATE TABLE `admin_markets` (`id` text PRIMARY KEY NOT NULL, `city` text NOT NULL, `state` text NOT NULL, `label` text NOT NULL, `status` text DEFAULT 'NEW' NOT NULL, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE `admin_case_files` (`id` text PRIMARY KEY NOT NULL, `market_id` text, `title` text NOT NULL, `status` text DEFAULT 'WATCH' NOT NULL, `jurisdiction` text, `agency` text, `vendor` text, `summary_json` text DEFAULT '{}' NOT NULL, `timeline_json` text DEFAULT '[]' NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `admin_case_files_market_idx` ON `admin_case_files` (`market_id`);
CREATE TABLE `admin_targets` (`id` text PRIMARY KEY NOT NULL, `market_id` text, `name` text NOT NULL, `organization` text, `role` text, `target_class` text NOT NULL, `email` text, `phone` text, `profile_url` text, `fit_score` integer DEFAULT 0 NOT NULL, `why_selected` text DEFAULT '' NOT NULL, `source_evidence_json` text DEFAULT '[]' NOT NULL, `internal_summary` text DEFAULT '' NOT NULL, `exposure_teaser` text DEFAULT '' NOT NULL, `report_url` text, `outreach_state` text DEFAULT 'RESEARCHED' NOT NULL, `referred_by_target_id` text, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `admin_targets_market_state_idx` ON `admin_targets` (`market_id`,`outreach_state`);
CREATE TABLE `admin_outreach` (`id` text PRIMARY KEY NOT NULL, `target_id` text NOT NULL, `kind` text DEFAULT 'INITIAL' NOT NULL, `subject` text NOT NULL, `body_text` text NOT NULL, `report_url` text NOT NULL, `approval_state` text DEFAULT 'DRAFT' NOT NULL, `approved_at` text, `queued_at` text, `sent_at` text, `provider_message_id` text, `follow_up_due_at` text, `stopped_at` text, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `admin_outreach_target_idx` ON `admin_outreach` (`target_id`,`approval_state`);
CREATE TABLE `admin_outreach_events` (`id` text PRIMARY KEY NOT NULL, `outreach_id` text NOT NULL, `target_id` text NOT NULL, `type` text NOT NULL, `metadata_json` text DEFAULT '{}' NOT NULL, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `admin_events_target_type_idx` ON `admin_outreach_events` (`target_id`,`type`);
CREATE TABLE `admin_radar_endpoints` (`id` text PRIMARY KEY NOT NULL, `market_id` text, `case_file_id` text, `type` text NOT NULL, `source_name` text NOT NULL, `url` text NOT NULL, `status` text DEFAULT 'ACTIVE' NOT NULL, `polling_enabled` integer DEFAULT 0 NOT NULL, `target_polls_per_day` integer DEFAULT 3 NOT NULL, `pulls` integer DEFAULT 0 NOT NULL, `changes` integer DEFAULT 0 NOT NULL, `relevant_changes` integer DEFAULT 0 NOT NULL, `research_escalations` integer DEFAULT 0 NOT NULL, `case_contributions` integer DEFAULT 0 NOT NULL, `publishable_events` integer DEFAULT 0 NOT NULL, `last_checked_at` text, `last_changed_at` text, `content_fingerprint` text, `yield_score` real DEFAULT 0 NOT NULL, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `admin_radar_url_uidx` ON `admin_radar_endpoints` (`url`);
CREATE TABLE `admin_radar_signals` (`id` text PRIMARY KEY NOT NULL, `endpoint_id` text NOT NULL, `case_file_id` text, `truth_level` text DEFAULT 'RADAR_SIGNAL' NOT NULL, `status` text DEFAULT 'NEW' NOT NULL, `title` text NOT NULL, `summary` text, `source_url` text NOT NULL, `detected_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `reviewed_at` text);
CREATE INDEX `admin_radar_signals_level_status_idx` ON `admin_radar_signals` (`truth_level`,`status`);
CREATE TABLE `admin_community_opportunities` (`id` text PRIMARY KEY NOT NULL, `case_file_id` text NOT NULL, `channel` text NOT NULL, `destination` text NOT NULL, `source_conversation_url` text, `why_now` text NOT NULL, `draft_title` text, `draft_body` text NOT NULL, `rules_json` text DEFAULT '{}' NOT NULL, `cooldown_until` text, `status` text DEFAULT 'DISCOVERED' NOT NULL, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
